def entry(base,src,status,relation,locator,full=False,kind='bounded_negative',terms=None):
 r={'status':status,'full_statement_found':full,'kind':kind,**src,'locator':locator,'relation':relation}
 if base:
  r['search_record']='work/invariants_arithmetic/inv_E_credit_searches.json#'+base
  r['terms_searched']=terms or list(searchby[base]['searches'])
  r['search_scope']='Entire supplied source searched textually with the saved exact regexes; only the explicitly stated original-source passages were opened and used for comparison. No worldwide or unread-source absence claim.'
 return r

def neg(base,src,relation,loc):return entry(base,src,'not_found_in_checked_scope',relation,loc)
def part(base,src,relation,loc,kind='partial_known_input'):return entry(base,src,'found_in_checked_scope',relation,loc,False,kind)
